from taf.gnb.oam.coam.vdu.services.emservice.http_client import EMServicev1HttpClient
from taf.gnb.oam.coam.vdu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1

@auto_token_refresh()
class EMServicev1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = EMServicev1HttpClient(base_url=con_details.base_url,
                                                  connection_alias=con_details.alias)

    def search_parameter_of_current_plan(self, para_name, timeout=30):
        return self.local_client.search_parameter_of_current_plan(para_name=para_name, timeout=timeout)

    def get_staged_plans(self):
        return self.local_client.get_staged_plans()

    def get_rnicmods_diff(self, timeout=30):
        return self.local_client.get_rnicmods_diff(timeout=timeout)

    def validate_plan(self, plan_id, timeout=30, wait_for_completion=False):
        operation = self.local_client.validate_plan(plan_id=plan_id, timeout=timeout)

        if wait_for_completion:
            method_name = "get_validate_plan_operation_status"

            return poll_status(instance=self.local_client, method_name=method_name,
                               operation_id=operation["actionId"], timeout=timeout, plan_id=plan_id)

        return operation

    def get_validate_plan_operation_status(self, plan_id, operation_id, timeout=30):
        return self.local_client.get_validate_plan_operation_status(plan_id=plan_id, operation_id=operation_id,
                                                                    timeout=timeout)

    def download_staged_plan_file(self, plan_id, include_auto_config_data=False):
        return self.local_client.download_staged_plan_file(plan_id=plan_id,
                                                           include_auto_config_data=include_auto_config_data)

    def get_staged_plan_validation_results(self, plan_id, validation_id, error_type):
        return self.local_client.get_staged_plan_validation_results(plan_id=plan_id, validation_id=validation_id,
                                                                    error_type=error_type)

    def fix_vdu_staged_plan_error(self, stage_plan_id, add_missing_obj, timeout):
        return self.local_client.fix_vdu_staged_plan_error(stage_plan_id=stage_plan_id,
                                                           add_missing_obj=add_missing_obj, timeout=timeout)

    def get_fix_vdu_staged_plan_operation_status(self, staged_plan_id, action_id, timeout=30):
        return self.local_client.get_fix_vdu_staged_plan_operation_status(staged_plan_id=staged_plan_id,
                                                                          action_id=action_id,
                                                                          timeout=timeout)
